create temp table discovery_cases(n integer primary key,payload jsonb);
create function pg_temp.discovery_setup(n integer)returns void language plpgsql as $$declare p private.private_beta_programs;v jsonb;begin
 perform pg_temp.beta_setup(n);perform pg_temp.beta_bot(n);select * into strict p from private.private_beta_programs where id=pg_temp.beta_id(n,'3000');
 v:=jsonb_build_object('version',1,'program_id',p.id,'tenant_id',p.tenant_id,'repository_sha',p.configuration->>'repository_sha','program_generation',p.generation::text,'bot_id',p.bot_control->>'bot_id','credential_sha256',p.bot_control->>'credential_sha256',
 'source_hash',repeat('c',64),'observed_at',clock_timestamp(),'expires_at',clock_timestamp()+interval '4 minutes','candidates',jsonb_build_array(jsonb_build_object('business_connection_id','Fixture_Business_CASE-'||n,'representative_user_id',(9000000+n)::text,'update_id','12','source_hash',repeat('d',64),'founder_chat_ids',jsonb_build_array((5000000+n)::text))));
 insert into discovery_cases(n,payload)values(n,v);end;$$;
create function pg_temp.discovery_record(n integer)returns void language plpgsql as $$declare v jsonb;begin select payload into strict v from discovery_cases where discovery_cases.n=$1;
 perform private.private_beta_business_discovery_record(pg_temp.beta_id(n,'2000'),pg_temp.beta_id(n,'3000'),(v->>'program_generation')::bigint,v::text);end;$$;

